steps.script:
var n = tree.root.get_node_or_null("/root/MainMenu/TutorialNudge")
if n == null or not n.visible:
	return "absent"
var b = n.get_node_or_null("Margin/VBox/Footer/DismissNudgeButton")
if b == null:
	return "no dismiss button"
b.pressed.emit()
return "dismissed"

var sc = tree.root.get_node_or_null("/root/MainMenu/ScrollContainer")
var b = tree.root.get_node_or_null("/root/MainMenu/ScrollContainer/MenuContainer/ButtonSection/TutorialButton")
if sc == null or b == null:
	return false
sc.ensure_control_visible(b)
return true

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
if ov == null:
	return "no TutorialOverlay"
var blocker = ov.card_blocker_rect()
if blocker.size == Vector2.ZERO:
	return "no blocking dialog open - the review modal should be up on this step"
var overlap = ov.card_blocker_overlap()
if overlap > 0.0:
	return "card buried %.0fpx under the dialog (card %s, dialog %s)" % [overlap, str(ov.card_rect()), str(blocker)]
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var blocker = ov.card_blocker_rect()
if blocker.size == Vector2.ZERO:
	return "no blocking dialog open"
var overlap = ov.card_blocker_overlap()
if overlap > 0.0:
	return "card buried %.0fpx under the dialog (card %s, dialog %s)" % [overlap, str(ov.card_rect()), str(blocker)]
if ov.card_content_width() >= 560.0:
	return "card never narrowed - still wrapped at %.0f" % ov.card_content_width()
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var w = ov.card_content_width()
if w <= 500.0:
	return "card stayed cramped at %.0f on the base canvas" % w
if ov.card_blocker_overlap() > 0.0:
	return "card overlaps the dialog again after the canvas grew"
return "ok"

var b = tree.root.get_node_or_null("/root/SecondaryMissionReviewDialog/OuterScroll/MainContainer/ButtonRow/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var blocker = ov.card_blocker_rect()
if blocker.size == Vector2.ZERO:
	return "no blocking dialog open - the guard prompt should be up on this step"
var overlap = ov.card_blocker_overlap()
if overlap > 0.0:
	return "card buried %.0fpx under the dialog (card %s, dialog %s)" % [overlap, str(ov.card_rect()), str(blocker)]
if ov.card_content_width() >= 560.0:
	return "card never narrowed - still wrapped at %.0f" % ov.card_content_width()
return "ok"

var b = tree.root.get_node_or_null("/root/GuardSelectionDialog/Content/Actions/KeepAutoGuards")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
if ov.card_blocker_rect().size != Vector2.ZERO:
	return "a dialog is still up on the waaagh step"
if not is_equal_approx(ov.card_content_width(), 560.0):
	return "card stayed narrow at %.0f with nothing to dodge" % ov.card_content_width()
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var blocker = ov.card_blocker_rect()
if blocker.size == Vector2.ZERO:
	return "no blocking dialog open - the stratagem panel should be up on this step"
var overlap = ov.card_blocker_overlap()
if overlap > 0.0:
	return "card buried %.0fpx under the dialog (card %s, dialog %s)" % [overlap, str(ov.card_rect()), str(blocker)]
if ov.card_content_width() >= 560.0:
	return "card never narrowed - still wrapped at %.0f" % ov.card_content_width()
return "ok"

var sp = tree.root.get_node_or_null("/root/Main/StratagemPanel")
if sp == null:
	return false
var b = sp.get_ok_button()
if b != null:
	b.pressed.emit()
	return true
return false

var host = null
for c in tree.root.get_node("/root/Main").get_children():
	if "Controller" in str(c.name):
		host = c
		break
if host == null:
	return "no controller node under Main to parent onto"
var d = AcceptDialog.new()
d.name = "ProbeControllerDialog"
d.min_size = Vector2i(700, 500)
d.exclusive = true
host.add_child(d)
DialogUtils.popup_at_bottom(d)
if d.get_parent() == tree.root or d.get_parent() == tree.root.get_node("/root/Main"):
	return "probe landed at a depth the cheap scan already covered - proves nothing"
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
if ov.card_blocker_rect().size == Vector2.ZERO:
	return "a dialog parented below /root/Main is still invisible to the overlay"
if ov.card_blocker_overlap() > 0.0:
	return "card buried %.0fpx under the controller-parented dialog" % ov.card_blocker_overlap()
var exit_btn = ov.get_node("InstructorCard/Margin/VBox/Footer/ExitTutorialButton")
if not exit_btn.disabled:
	return "card's Exit Tutorial still looks live under a modal that swallows clicks"
return "ok"

var d = tree.root.get_node("/root/Main").find_child("ProbeControllerDialog", true, false)
if d == null:
	return false
var b = d.get_meta("tutorial_exit_button", null)
return b != null and is_instance_valid(b) and b.is_visible_in_tree()

var d = tree.root.get_node("/root/Main").find_child("ProbeControllerDialog", true, false)
if d == null:
	return false
var pm = PopupMenu.new()
pm.name = "ProbeDropdown"
pm.add_item("Tactical")
d.get_parent().add_child(pm)
pm.popup(Rect2i(400, 400, 200, 80))
return true

var d = tree.root.get_node("/root/Main").find_child("ProbeControllerDialog", true, false)
if d != null:
	d.queue_free()
return true

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var pm = tree.root.get_node("/root/Main").find_child("ProbeDropdown", true, false)
if pm == null or not pm.visible:
	return "the dropdown closed on its own - this check proves nothing"
if ov.card_blocker_rect().size != Vector2.ZERO:
	return "an open dropdown is being treated as a modal - the card would fly to the flank whenever a list is opened"
if not is_equal_approx(ov.card_content_width(), 560.0):
	return "card stayed narrow at %.0f with only a dropdown open" % ov.card_content_width()
return "ok"

var pm = tree.root.get_node("/root/Main").find_child("ProbeDropdown", true, false)
if pm != null:
	pm.queue_free()
return true
